/* ──────────────────────────────────────────────────────────
   COMMISSION RULE — effective date timeline
────────────────────────────────────────────────────────── */
--color-timeline-active:  oklch(62% 0.24 292 / 0.8);
--color-timeline-past:    oklch(40% 0.02 264 / 0.5);
--color-timeline-future:  oklch(60% 0.22 230 / 0.5);
--color-timeline-track:   oklch(22% 0.02 264);
