## 14. CommissionPreview Component

### 14a. Full spec

```tsx
// components/commissions/CommissionPreview.tsx — Client Component ("use client")

interface CommissionPreviewRule {
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number
}

interface CommissionPreviewProps {
  price: number       // cents — example booking price (default: 50000 = $500)
  tip: number         // cents — example tip (default: 5000 = $50)
  rule: CommissionPreviewRule
  showExampleLabel?: boolean  // default true
  className?: string
}

// Calculation (pure function — no side effects)
function calculateCommission(price: number, tip: number, rule: CommissionPreviewRule): {
  commission: number
  tipCommission: number
  total: number
  breakdown: string
} {
  let commission = 0
  const parts: string[] = []

  if (rule.percentage != null && rule.flat_fee_cents != null) {
    commission = Math.round(price * rule.percentage / 100) + rule.flat_fee_cents
    parts.push(`${formatCurrency(price)} × ${rule.percentage}% + ${formatCurrency(rule.flat_fee_cents)}`)
  } else if (rule.percentage != null) {
    commission = Math.round(price * rule.percentage / 100)
    parts.push(`${formatCurrency(price)} × ${rule.percentage}%`)
  } else if (rule.flat_fee_cents != null) {
    commission = rule.flat_fee_cents
    parts.push(`${formatCurrency(rule.flat_fee_cents)} flat`)
  }

  const tipCommission = Math.round(tip * rule.tip_split_pct / 100)
  if (tip > 0) {
    parts.push(`${formatCurrency(tip)} tip × ${rule.tip_split_pct}%`)
  }

  return {
    commission,
    tipCommission,
    total: commission + tipCommission,
    breakdown: parts.join(' + '),
  }
}
```

**Render:**
```tsx
export function CommissionPreview({ price, tip, rule, showExampleLabel = true, className }: CommissionPreviewProps) {
  const { commission, tipCommission, total, breakdown } = calculateCommission(price, tip, rule)
  const isValid = rule.percentage != null || rule.flat_fee_cents != null

  if (!isValid) return (
    <div className={cn('commission-preview opacity-50', className)}>
      <p className="commission-preview-label">Preview</p>
      <p className="text-xs text-muted-foreground mt-1">Enter a commission structure above to see a preview.</p>
    </div>
  )

  return (
    <div className={cn('commission-preview', className)}>
      {showExampleLabel && (
        <p className="commission-preview-label mb-2">
          Preview · example: {formatCurrency(price)} booking + {formatCurrency(tip)} tip
        </p>
      )}
      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">{breakdown}</span>
          <span className="commission-preview-value tabular-nums">{formatCurrency(commission)}</span>
        </div>
        {tip > 0 && tipCommission > 0 && (
          <div className="flex items-center justify-between">
            <span className="text-xs text-muted-foreground">
              {formatCurrency(tip)} × {rule.tip_split_pct}% tip
            </span>
            <span className="commission-preview-value tabular-nums">+{formatCurrency(tipCommission)}</span>
          </div>
        )}
        <Separator className="my-1" />
        <div className="flex items-center justify-between">
          <span className="commission-preview-label">Artist receives</span>
          <span className="commission-preview-total tabular-nums">{formatCurrency(total)}</span>
        </div>
      </div>
    </div>
  )
}
```

